91	function parseAgent(filePath) {
92	  try {
93	    const content = fs.readFileSync(filePath, 'utf-8');
94	    const { data, content: body } = matter(content);
95	    const stats = fs.statSync(filePath);
96	    return {
97	      filename: path.basename(filePath, '.md'),
98	      path: filePath,
99	      frontmatter: data,
100	      name: data.name || path.basename(filePath, '.md'),
101	      description: data.description || '',
102	      model: data.model || '',
103	      tools: data.tools || '',
104	      body: body.trim(),
105	      raw: content,
106	      updatedAt: stats.mtime.toISOString(),
107	    };
108	  } catch (e) {
109	    return null;
110	  }
111	}
