113	function listAgents(dir) {
114	  try {
115	    if (!fs.existsSync(dir)) return [];
116	    return fs.readdirSync(dir)
117	      .filter(f => f.endsWith('.md'))
118	      .map(f => parseAgent(path.join(dir, f)))
119	      .filter(Boolean);
120	  } catch {
121	    return [];
122	  }
123	}
124	
125	function listMdFiles(dir) {
126	  try {
127	    if (!fs.existsSync(dir)) return [];
128	    return fs.readdirSync(dir)
129	      .filter(f => f.endsWith('.md'))
130	      .map(f => {
131	        const filePath = path.join(dir, f);
132	        const content = readFileSafe(filePath);
133	        const stats = fs.statSync(filePath);
134	        return {
135	          name: f.replace('.md', ''),
136	          content: content || '',
137	          path: filePath,
138	          updatedAt: stats.mtime.toISOString(),
139	        };
140	      });
141	  } catch {
142	    return [];
143	  }
144	}
