146	function discoverProjects(dirs) {
147	  const projects = [];
148	  for (const dir of dirs) {
149	    const resolved = dir.replace(/^~/, HOME);
150	    if (!fs.existsSync(resolved)) continue;
151	    try {
152	      const entries = fs.readdirSync(resolved, { withFileTypes: true });
153	      for (const entry of entries) {
154	        if (!entry.isDirectory()) continue;
155	        if (entry.name.startsWith('.') || entry.name === 'node_modules') continue;
156	        const projectPath = path.join(resolved, entry.name);
157	        const hasClaudeDir = fs.existsSync(path.join(projectPath, '.claude'));
158	        const hasClaudeMd = fs.existsSync(path.join(projectPath, 'CLAUDE.md'));
159	        const hasPackageJson = fs.existsSync(path.join(projectPath, 'package.json'));
160	        const hasPubspec = fs.existsSync(path.join(projectPath, 'pubspec.yaml'));
161	        if (hasClaudeDir || hasClaudeMd || hasPackageJson || hasPubspec) {
162	          const agents = listAgents(path.join(projectPath, '.claude', 'agents'));
163	          const commands = listMdFiles(path.join(projectPath, '.claude', 'commands'));
164	          const rules = listMdFiles(path.join(projectPath, '.claude', 'rules'));
165	          projects.push({
166	            id: Buffer.from(projectPath).toString('base64url'),
167	            name: entry.name,
168	            path: projectPath,
169	            displayPath: projectPath.replace(HOME, '~'),
170	            hasClaudeDir,
171	            hasClaudeMd,
172	            agentCount: agents.length,
173	            commandCount: commands.length,
174	            ruleCount: rules.length,
175	            agents,
176	            commands: commands.map(c => c.name),
177	            rules: rules.map(r => r.name),
178	          });
179	        }
180	      }
181	    } catch {}
182	  }
183	  return projects;
184	}
