356	app.get('/api/browse', (req, res) => {
357	  let targetPath = (req.query.path || HOME).replace(/^~/, HOME);
358	  targetPath = path.resolve(targetPath);
359	
360	  try {
361	    if (!fs.existsSync(targetPath)) {
362	      return res.status(404).json({ error: 'Path not found' });
363	    }
364	    const stat = fs.statSync(targetPath);
365	    if (!stat.isDirectory()) {
366	      return res.status(400).json({ error: 'Not a directory' });
367	    }
368	
369	    const entries = fs.readdirSync(targetPath, { withFileTypes: true });
370	    const dirs = entries
371	      .filter(e => e.isDirectory() && !e.name.startsWith('.') && e.name !== 'node_modules' && e.name !== '__pycache__')
372	      .map(e => ({
373	        name: e.name,
374	        path: path.join(targetPath, e.name),
375	        displayPath: path.join(targetPath, e.name).replace(HOME, '~'),
376	        hasProjects: false,
377	      }))
378	      .sort((a, b) => a.name.localeCompare(b.name));
379	
380	    for (const dir of dirs) {
381	      try {
382	        const sub = fs.readdirSync(dir.path, { withFileTypes: true });
383	        dir.hasProjects = sub.some(s =>
384	          s.isDirectory() && (
385	            fs.existsSync(path.join(dir.path, s.name, '.claude')) ||
386	            fs.existsSync(path.join(dir.path, s.name, 'CLAUDE.md')) ||
387	            fs.existsSync(path.join(dir.path, s.name, 'package.json')) ||
388	            fs.existsSync(path.join(dir.path, s.name, 'pubspec.yaml'))
389	          )
390	        );
391	      } catch {}
392	    }
393	
394	    const parts = targetPath.split(path.sep).filter(Boolean);
395	    const breadcrumbs = parts.map((part, i) => ({
396	      name: i === 0 && targetPath.startsWith(HOME) ? '~' : part,
397	      path: path.sep + parts.slice(0, i + 1).join(path.sep),
398	    }));
399	
400	    if (targetPath.startsWith(HOME)) {
401	      const homeIndex = HOME.split(path.sep).filter(Boolean).length - 1;
402	      breadcrumbs.splice(0, homeIndex + 1, { name: '~', path: HOME });
403	    }
404	
405	    res.json({
406	      current: targetPath,
407	      displayPath: targetPath.replace(HOME, '~'),
408	      parent: path.dirname(targetPath) !== targetPath ? path.dirname(targetPath) : null,
409	      breadcrumbs,
410	      directories: dirs,
411	    });
412	  } catch (e) {
413	    res.status(500).json({ error: 'Cannot read directory' });
414	  }
415	});
